    /// Append the ACPI MADT Generic MSI Frame (type 0x0D).  The frame is
    /// populated from the exact GIC configuration chosen at runtime, so ACPI
    /// cannot drift from the Hypervisor.framework MSI region.
    private static func makeMADT(msiFrame: FluxGIC.MSIFrame) -> [UInt8] {
        var table = madtAML
        var frame: [UInt8] = [
            0x0D, 0x18,             // Type, Length
            0x00, 0x00,             // Reserved
            0x00, 0x00, 0x00, 0x00, // MSI Frame ID
        ]
        withUnsafeBytes(of: UInt64(msiFrame.base).littleEndian) {
            frame.append(contentsOf: $0)
        }
        frame.append(contentsOf: [
            0x00, 0x00, 0x00, 0x00, // Flags: SPI base/count are valid
        ])
        withUnsafeBytes(of: UInt16(msiFrame.spiCount).littleEndian) {
            frame.append(contentsOf: $0)
        }
        withUnsafeBytes(of: UInt16(msiFrame.spiBase).littleEndian) {
            frame.append(contentsOf: $0)
        }
        table.append(contentsOf: frame)

        let length = UInt32(table.count).littleEndian
        withUnsafeBytes(of: length) { bytes in
            table.replaceSubrange(4..<8, with: bytes)
        }
        return table
    }

