    private init() {
        var tables = [UInt8]()

        func align(_ value: Int, to alignment: Int) -> Int {
            (value + alignment - 1) & ~(alignment - 1)
        }

        // 1. DSDT
        let dOff = tables.count
        var dsdtData = Self.dsdtAML
        // Initialize DSDT checksum byte to 0 so QEMU linker-loader ADD_CHECKSUM
        // computes the correct checksum in firmware.
        dsdtData[9] = 0
        tables.append(contentsOf: dsdtData)

        // 2. FADT (align 8)
        let padFadt = align(tables.count, to: 8) - tables.count
        tables.append(contentsOf: [UInt8](repeating: 0, count: padFadt))
        let fOff = tables.count
        var fadtData = Self.fadtAML
        fadtData[9] = 0

        // IA-PC Boot Architecture Flags @ FADT offset 109..110.
        // Bit 3 = MSI_NOT_SUPPORTED.  The virtual GIC has already reserved a
        // MADT-advertised message-based SPI MSI frame, so Windows may allocate
        // the endpoint's MSI-X vector.
        let bootArchOffset = 109
        let oldBootArch =
            UInt16(fadtData[bootArchOffset]) |
            (UInt16(fadtData[bootArchOffset + 1]) << 8)

        let newBootArch = oldBootArch & ~0x0008

        fadtData[bootArchOffset] = UInt8(newBootArch & 0xFF)
        fadtData[bootArchOffset + 1] = UInt8((newBootArch >> 8) & 0xFF)

        print(
            "⚙️ [FluxACPI] FADT Boot Architecture: " +
            "0x\(String(oldBootArch, radix: 16)) -> " +
            "0x\(String(newBootArch, radix: 16)) " +
            "(MSI_NOT_SUPPORTED=0)"
        )
        // 32-bit DSDT pointer at offset 40 is initially relative offset of DSDT
        let dOff32 = UInt32(dOff)
        withUnsafeBytes(of: dOff32.littleEndian) { bytes in
            for i in 0..<4 {
                fadtData[40 + i] = bytes[i]
            }
        }
        // X_DSDT pointer at offset 140 is initially relative offset of DSDT
        let dOff64 = UInt64(dOff)
        withUnsafeBytes(of: dOff64.littleEndian) { bytes in
            for i in 0..<8 {
                fadtData[140 + i] = bytes[i]
            }
        }
        tables.append(contentsOf: fadtData)

        // 3. MADT (align 8)
        let padMadt = align(tables.count, to: 8) - tables.count
        tables.append(contentsOf: [UInt8](repeating: 0, count: padMadt))
        let mOff = tables.count
        guard let msiFrame = FluxGIC.msiFrame else {
            fatalError("GIC MSI frame must be configured before ACPI is served")
        }
        var madtData = Self.makeMADT(msiFrame: msiFrame)
        madtData[9] = 0
        tables.append(contentsOf: madtData)

        // 4. GTDT (align 8)
        let padGtdt = align(tables.count, to: 8) - tables.count
        tables.append(contentsOf: [UInt8](repeating: 0, count: padGtdt))
        let gOff = tables.count
        var gtdtData = Self.gtdtAML
        gtdtData[9] = 0
        tables.append(contentsOf: gtdtData)

        // 5. SPCR (align 8)
        let padSpcr = align(tables.count, to: 8) - tables.count
        tables.append(contentsOf: [UInt8](repeating: 0, count: padSpcr))
        let sOff = tables.count
        var spcrData = Self.spcrAML
        spcrData[9] = 0
        tables.append(contentsOf: spcrData)

        // 6. MCFG (align 8)
        let padMcfg = align(tables.count, to: 8) - tables.count
        tables.append(contentsOf: [UInt8](repeating: 0, count: padMcfg))
        let mcOff = tables.count
        var mcfgData = Self.mcfgAML
        mcfgData[9] = 0
        tables.append(contentsOf: mcfgData)

        // 7. XSDT (align 8)
        let padXsdt = align(tables.count, to: 8) - tables.count
        tables.append(contentsOf: [UInt8](repeating: 0, count: padXsdt))
        let xOff = tables.count

        // Build 76-byte XSDT: 36-byte header + 5 * 8-byte table entries
        let xsdtLength: UInt32 = 36 + 5 * 8
        var xsdt = [UInt8]()
        xsdt.append(contentsOf: [UInt8]("XSDT".utf8))
        withUnsafeBytes(of: xsdtLength.littleEndian) { xsdt.append(contentsOf: $0) }
        xsdt.append(1) // Revision 1
        xsdt.append(0) // Checksum (filled by loader)
        xsdt.append(contentsOf: [UInt8]("FLUX  ".utf8)) // OEMID (6)
        xsdt.append(contentsOf: [UInt8]("FLUXVM  ".utf8)) // OEMTableID (8)
        withUnsafeBytes(of: UInt32(1).littleEndian) { xsdt.append(contentsOf: $0) } // OEMRev
        xsdt.append(contentsOf: [UInt8]("INTL".utf8)) // CreatorID (4)
        withUnsafeBytes(of: UInt32(0x20260408).littleEndian) { xsdt.append(contentsOf: $0) } // CreatorRev

        // Table entry offsets initially relative to tablesBlob
        let entries: [UInt64] = [UInt64(fOff), UInt64(mOff), UInt64(gOff), UInt64(sOff), UInt64(mcOff)]
        for entry in entries {
            withUnsafeBytes(of: entry.littleEndian) { xsdt.append(contentsOf: $0) }
        }
        tables.append(contentsOf: xsdt)

        // 8. RSDT (align 8)
        let padRsdt = align(tables.count, to: 8) - tables.count
        tables.append(contentsOf: [UInt8](repeating: 0, count: padRsdt))
        let rOff = tables.count

        // Build 56-byte RSDT: 36-byte header + 5 * 4-byte table entries
        let rsdtLength: UInt32 = 36 + 5 * 4
        var rsdt = [UInt8]()
        rsdt.append(contentsOf: [UInt8]("RSDT".utf8))
        withUnsafeBytes(of: rsdtLength.littleEndian) { rsdt.append(contentsOf: $0) }
        rsdt.append(1) // Revision 1
        rsdt.append(0) // Checksum (filled by loader)
        rsdt.append(contentsOf: [UInt8]("FLUX  ".utf8)) // OEMID (6)
        rsdt.append(contentsOf: [UInt8]("FLUXVM  ".utf8)) // OEMTableID (8)
        withUnsafeBytes(of: UInt32(1).littleEndian) { rsdt.append(contentsOf: $0) } // OEMRev
        rsdt.append(contentsOf: [UInt8]("INTL".utf8)) // CreatorID (4)
        withUnsafeBytes(of: UInt32(0x20260408).littleEndian) { rsdt.append(contentsOf: $0) } // CreatorRev

        // Table entry offsets initially relative to tablesBlob
        let rsdtEntries: [UInt32] = [UInt32(fOff), UInt32(mOff), UInt32(gOff), UInt32(sOff), UInt32(mcOff)]
        for entry in rsdtEntries {
            withUnsafeBytes(of: entry.littleEndian) { rsdt.append(contentsOf: $0) }
        }
        tables.append(contentsOf: rsdt)

        self.dsdtOffset = UInt32(dOff)
        self.fadtOffset = UInt32(fOff)
        self.madtOffset = UInt32(mOff)
        self.gtdtOffset = UInt32(gOff)
        self.spcrOffset = UInt32(sOff)
        self.mcfgOffset = UInt32(mcOff)
        self.xsdtOffset = UInt32(xOff)
        self.rsdtOffset = UInt32(rOff)
        self.tablesBlob = tables

        // 9. RSDP (36 bytes ACPI 2.0)
        var rsdp = [UInt8]()
        rsdp.append(contentsOf: [UInt8]("RSD PTR ".utf8)) // 8 bytes
        rsdp.append(0) // Checksum byte 8
        rsdp.append(contentsOf: [UInt8]("FLUX  ".utf8)) // OEMID (6)
        rsdp.append(2) // Revision 2
        withUnsafeBytes(of: UInt32(rOff).littleEndian) { rsdp.append(contentsOf: $0) } // RsdtAddress (offset in tables)
        withUnsafeBytes(of: UInt32(36).littleEndian) { rsdp.append(contentsOf: $0) } // Length 36
        withUnsafeBytes(of: UInt64(xOff).littleEndian) { rsdp.append(contentsOf: $0) } // XsdtAddress (offset in tables)
        rsdp.append(0) // Extended Checksum byte 32
        rsdp.append(contentsOf: [UInt8](repeating: 0, count: 3)) // Reserved (3)
        self.rsdpBlob = rsdp

        // 10. Linker/Loader Commands (128 bytes each)
        var loader = [UInt8]()

        func makeAllocCmd(file: String, align: UInt32, zone: UInt8) -> [UInt8] {
            var cmd = [UInt8](repeating: 0, count: 128)
            // command = 1 (ALLOCATE)
            withUnsafeBytes(of: UInt32(1).littleEndian) { cmd.replaceSubrange(0..<4, with: $0) }
            let nameBytes = [UInt8](file.utf8.prefix(55))
            cmd.replaceSubrange(4..<(4 + nameBytes.count), with: nameBytes)
            withUnsafeBytes(of: align.littleEndian) { cmd.replaceSubrange(60..<64, with: $0) }
            cmd[64] = zone
            return cmd
        }

        func makePointerCmd(destFile: String, srcFile: String, offset: UInt32, size: UInt8) -> [UInt8] {
            var cmd = [UInt8](repeating: 0, count: 128)
            // command = 2 (ADD_POINTER)
            withUnsafeBytes(of: UInt32(2).littleEndian) { cmd.replaceSubrange(0..<4, with: $0) }
            let destBytes = [UInt8](destFile.utf8.prefix(55))
            cmd.replaceSubrange(4..<(4 + destBytes.count), with: destBytes)
            let srcBytes = [UInt8](srcFile.utf8.prefix(55))
            cmd.replaceSubrange(60..<(60 + srcBytes.count), with: srcBytes)
            withUnsafeBytes(of: offset.littleEndian) { cmd.replaceSubrange(116..<120, with: $0) }
            cmd[120] = size
            return cmd
        }

        func makeChecksumCmd(file: String, offset: UInt32, start: UInt32, length: UInt32) -> [UInt8] {
            var cmd = [UInt8](repeating: 0, count: 128)
            // command = 3 (ADD_CHECKSUM)
            withUnsafeBytes(of: UInt32(3).littleEndian) { cmd.replaceSubrange(0..<4, with: $0) }
            let fileBytes = [UInt8](file.utf8.prefix(55))
            cmd.replaceSubrange(4..<(4 + fileBytes.count), with: fileBytes)
            withUnsafeBytes(of: offset.littleEndian) { cmd.replaceSubrange(60..<64, with: $0) }
            withUnsafeBytes(of: start.littleEndian) { cmd.replaceSubrange(64..<68, with: $0) }
            withUnsafeBytes(of: length.littleEndian) { cmd.replaceSubrange(68..<72, with: $0) }
            return cmd
        }

        let tablesFile = "etc/acpi/tables"
        let rsdpFile = "etc/acpi/rsdp"

        // Command 1: ALLOCATE tables (align 4096, zone HIGH=1)
        loader.append(contentsOf: makeAllocCmd(file: tablesFile, align: 4096, zone: 1))
        // Command 2: ALLOCATE rsdp (align 16, zone HIGH=1)
        loader.append(contentsOf: makeAllocCmd(file: rsdpFile, align: 16, zone: 1))
        // Command 3: ADD_POINTER rsdp.RsdtAddress (offset 16, size 4) -> tables at rOff
        loader.append(contentsOf: makePointerCmd(destFile: rsdpFile, srcFile: tablesFile, offset: 16, size: 4))
        // Command 4: ADD_POINTER rsdp.XsdtAddress (offset 24, size 8) -> tables at xOff
        loader.append(contentsOf: makePointerCmd(destFile: rsdpFile, srcFile: tablesFile, offset: 24, size: 8))
        // Command 5: ADD_CHECKSUM rsdp standard (offset 8, start 0, length 20)
        loader.append(contentsOf: makeChecksumCmd(file: rsdpFile, offset: 8, start: 0, length: 20))
        // Command 6: ADD_CHECKSUM rsdp extended (offset 32, start 0, length 36)
        loader.append(contentsOf: makeChecksumCmd(file: rsdpFile, offset: 32, start: 0, length: 36))
        // Command 7a: ADD_POINTER FADT.DSDT (offset fOff + 40, size 4) -> tables at dOff
        loader.append(contentsOf: makePointerCmd(destFile: tablesFile, srcFile: tablesFile, offset: UInt32(fOff + 40), size: 4))
        // Command 7b: ADD_POINTER FADT.X_DSDT (offset fOff + 140, size 8) -> tables at dOff
        loader.append(contentsOf: makePointerCmd(destFile: tablesFile, srcFile: tablesFile, offset: UInt32(fOff + 140), size: 8))
        // Command 8: ADD_CHECKSUM DSDT
        loader.append(contentsOf: makeChecksumCmd(file: tablesFile, offset: UInt32(dOff + 9), start: UInt32(dOff), length: UInt32(Self.dsdtAML.count)))
        // Command 9: ADD_CHECKSUM FADT
        loader.append(contentsOf: makeChecksumCmd(file: tablesFile, offset: UInt32(fOff + 9), start: UInt32(fOff), length: UInt32(Self.fadtAML.count)))
        // Command 10: ADD_CHECKSUM MADT
        loader.append(contentsOf: makeChecksumCmd(file: tablesFile, offset: UInt32(mOff + 9), start: UInt32(mOff), length: UInt32(madtData.count)))
        // Command 11: ADD_CHECKSUM GTDT
        loader.append(contentsOf: makeChecksumCmd(file: tablesFile, offset: UInt32(gOff + 9), start: UInt32(gOff), length: UInt32(Self.gtdtAML.count)))
        // Command 12: ADD_CHECKSUM SPCR
        loader.append(contentsOf: makeChecksumCmd(file: tablesFile, offset: UInt32(sOff + 9), start: UInt32(sOff), length: UInt32(Self.spcrAML.count)))
        // Command 13: ADD_CHECKSUM MCFG
        loader.append(contentsOf: makeChecksumCmd(file: tablesFile, offset: UInt32(mcOff + 9), start: UInt32(mcOff), length: UInt32(Self.mcfgAML.count)))
        // Command 14: ADD_POINTER XSDT[0] -> FADT
        loader.append(contentsOf: makePointerCmd(destFile: tablesFile, srcFile: tablesFile, offset: UInt32(xOff + 36), size: 8))
        // Command 15: ADD_POINTER XSDT[1] -> MADT
        loader.append(contentsOf: makePointerCmd(destFile: tablesFile, srcFile: tablesFile, offset: UInt32(xOff + 44), size: 8))
        // Command 16: ADD_POINTER XSDT[2] -> GTDT
        loader.append(contentsOf: makePointerCmd(destFile: tablesFile, srcFile: tablesFile, offset: UInt32(xOff + 52), size: 8))
        // Command 17: ADD_POINTER XSDT[3] -> SPCR
        loader.append(contentsOf: makePointerCmd(destFile: tablesFile, srcFile: tablesFile, offset: UInt32(xOff + 60), size: 8))
        // Command 18: ADD_POINTER XSDT[4] -> MCFG
        loader.append(contentsOf: makePointerCmd(destFile: tablesFile, srcFile: tablesFile, offset: UInt32(xOff + 68), size: 8))
        // Command 19: ADD_CHECKSUM XSDT
        loader.append(contentsOf: makeChecksumCmd(file: tablesFile, offset: UInt32(xOff + 9), start: UInt32(xOff), length: xsdtLength))
        // Command 20: ADD_POINTER RSDT[0] -> FADT
        loader.append(contentsOf: makePointerCmd(destFile: tablesFile, srcFile: tablesFile, offset: UInt32(rOff + 36), size: 4))
        // Command 21: ADD_POINTER RSDT[1] -> MADT
        loader.append(contentsOf: makePointerCmd(destFile: tablesFile, srcFile: tablesFile, offset: UInt32(rOff + 40), size: 4))
        // Command 22: ADD_POINTER RSDT[2] -> GTDT
        loader.append(contentsOf: makePointerCmd(destFile: tablesFile, srcFile: tablesFile, offset: UInt32(rOff + 44), size: 4))
        // Command 23: ADD_POINTER RSDT[3] -> SPCR
        loader.append(contentsOf: makePointerCmd(destFile: tablesFile, srcFile: tablesFile, offset: UInt32(rOff + 48), size: 4))
        // Command 24: ADD_POINTER RSDT[4] -> MCFG
        loader.append(contentsOf: makePointerCmd(destFile: tablesFile, srcFile: tablesFile, offset: UInt32(rOff + 52), size: 4))
        // Command 25: ADD_CHECKSUM RSDT
        loader.append(contentsOf: makeChecksumCmd(file: tablesFile, offset: UInt32(rOff + 9), start: UInt32(rOff), length: rsdtLength))


        self.loaderBlob = loader
    }
}
